type createGainUseCaseMock struct {
	execute func(createGainCtx gainprojection.CreateGainContext) (*gainprojection.GainStat, error)
}

func (m *createGainUseCaseMock) Execute(createGainCtx gainprojection.CreateGainContext) (*gainprojection.GainStat, error) {
	return m.execute(createGainCtx)
}

func TestCreateGainSuccess(t *testing.T) {
	useCaseMock := &createGainUseCaseMock{
		execute: func(createGainCtx gainprojection.CreateGainContext) (*gainprojection.GainStat, error) {
			return &gainprojection.GainStat{ProjectionIsFound: true, ProjectionIsAlreadyDone: false, Gain: &gainprojection.GainResponse{}}, nil
		},
	}

	handler := NewCreateGainHandler(useCaseMock)
	w := httptest.NewRecorder()
	router := gin.Default()
	apiRouter := router.Group("/v1")
	apiRouter.POST("/gain-projection/:id/create-gain", handler.Handle)

	body := []byte(`
	{
		"pay_in": "2023-12-30T00:00:00+00:00",
		"value": 500
	}`)
	req, _ := http.NewRequest("POST", "/v1/gain-projection/71e31eb6-dde2-4dcb-b7ef-c7e8a699c628/create-gain", bytes.NewReader(body))
	userToken := "eyJhbGciOiJSUzI1NiIsInR5cCIgOiAiSldUIiwia2lkIiA6ICJRSnVoUjlFSFBIWTZFT195VjV4M1BTZWUzakRLNUs4M0lQMjJwYjFxZXFvIn0..AcRSnpgzjsuJL2n_QaRF1idkwDzwNpWNX3wiEOFXkqTG35lr4PYVYPxnhryvRvVVOvN_CUY-AaVmF_YSgR4s6JM3Oca5JFFf7T6fX5lXgj0SbQCUbbyh7Em3BemiNKr_T3wucAyO824MjGXP0smciCnnlWvq-apJDTB_R4EisDJubY_E_zpCmTfYMm0NcJ8aKB2ku8mACKgE2ZJ7WsHkKNmjaFeyU9KjGMmNKtFthYISKqRQW-6u2xPjCkpFt4_HoJ01PgjFrrJacWDlUHxVoSILcaH_Vg-WHrKppIkzgdOg5phB2zVtcakRhPhqzV4EX_jXJp2SgK4umf6ivTC3lg"
	req.Header.Add(idpauth.AUTH_HEADER, userToken)

	router.ServeHTTP(w, req)
	bodyExpected := `{"id":"","gain_projection_id":"","pay_in":"0001-01-01T00:00:00Z","description":"","value":0,"is_passive":false,"category":{"id":0,"category":""}}`
	assert.Equal(t, bodyExpected, w.Body.String())
	assert.Equal(t, http.StatusCreated, w.Code)
}

